-- Distortion World's new wild Pokémon (docs/28). Generated by `tsx scripts/patch-hh-distortion-pool.ts --sql`: do
-- not edit by hand. Patches only its pool, over the admin's later edits: Haunter and Dusclops as reliefs (Lv.55–59),
-- Houndoom, Sableye, Froslass, Gourgeist, Palossand, Mimikyu and Polteageist (Lv.65–69); then `configVersion` + 1.
-- Safe to run again.
begin;
insert into area_wild_pool (id, area_id, dex, weight, min_level, max_level)
select v.id::uuid, v.area_id::uuid, v.dex, v.weight, v.min_level, v.max_level
from (values
  ('6ce4772b-4a17-5f67-8b63-b144b1caa5d1', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 93, 12, 55, 58),
  ('a44372ce-4c22-5b5f-9268-96ce1c43ceec', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 356, 12, 56, 59),
  ('fa4df77a-680a-570e-9d97-747065344b34', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 229, 15, 65, 69),
  ('54d8502e-4fff-5937-bf3d-93c159ea49d8', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 302, 15, 65, 69),
  ('89ebe56d-623d-5c05-b2c1-95e5a491be63', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 478, 15, 65, 69),
  ('5f2437b7-5863-538f-a5be-05f34e1aa393', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 711, 15, 65, 69),
  ('6f2b764b-57f2-5172-b220-a824936752f3', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 770, 15, 65, 69),
  ('bf476957-8ef2-5b26-9135-46e9d1badc27', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 778, 15, 65, 69),
  ('510bb241-269d-52da-a3e0-d4146e5434d9', 'cfff57e0-5175-545c-9e68-a2e2e64d7d45', 855, 15, 65, 69)
) v (id, area_id, dex, weight, min_level, max_level)
where exists (select 1 from areas a where a.id = v.area_id::uuid)
  and not exists (select 1 from area_wild_pool p where p.area_id = v.area_id::uuid and p.dex = v.dex)
on conflict (id) do nothing;
insert into game_config (key, value) values ('configVersion', '1'::jsonb) on conflict (key) do update set value = to_jsonb(coalesce((game_config.value #>> '{}')::int, 0) + 1);
commit;
